# hotel-api

Quotes for group bookings: rooms, discounts, and the availability blocks we
send to the hotel's PMS.

## Develop

```bash
npm install
npm test
```

## Tickets

Work is tracked in the `HOT` project. Branch names and PR titles carry the
ticket key (`feat/hot-123-short-name`). Read tickets from the terminal with
the `tracker` CLI (`tracker --help`).
export type RoomType = "Single" | "Double" | "Suite";

export interface RoomLine {
  roomType: RoomType;
  count: number;
  nights: number;
  nightlyRate: number;
}

export interface Quote {
  id: string;
  customerId: string;
  arrival: string;
  rooms: RoomLine[];
  legacyTotal: number;
  discountCode?: string;
}

export function quoteTotal(quote: Quote): number {
  return quote.rooms.reduce(
    (sum, line) => sum + line.count * line.nights * line.nightlyRate,
    0,
  );
}
import { Quote } from "./quote";
import { db } from "../db";

export async function findQuote(id: string): Promise<Quote | undefined> {
  const row = await db.one("select * from quotes where id = $1", [id]);
  if (!row) return undefined;
  return {
    id: row.id,
    customerId: row.customer_id,
    arrival: row.arrival,
    rooms: row.rooms,
    legacyTotal: row.legacy_total,
    discountCode: row.discount_code ?? undefined,
  };
}

